{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Build edges with mutual reachability weight
    edges = []
    for u, v, d in distances:
        w = max(core_dist[u], core_dist[v], d)
        # canonical order: u <= v string comparison
        if u < v:
            edges.append((w, u, v))
        else:
            edges.append((w, v, u))

    # Sort by weight, then by endpoints for determinism
    edges.sort()

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Graph is disconnected; cannot form MST')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
